head.b:skin:
/* ==========================================
   GLASSMORPHISM THEME
   Frosted glass, gradient depth, aurora
   ========================================== */

<Group description="Glass Colors" selector="body">
    <Variable name="accent.purple" description="Purple accent" type="color" default="#a855f7" value="#a855f7"/>
    <Variable name="accent.cyan" description="Cyan accent" type="color" default="#06b6d4" value="#06b6d4"/>
    <Variable name="bg.dark1" description="Bg dark start" type="color" default="#1a0533" value="#1a0533"/>
    <Variable name="bg.dark2" description="Bg dark end" type="color" default="#0d1b4b" value="#0d1b4b"/>
</Group>

:root {
    --purple: #a855f7;
    --cyan: #06b6d4;
    --pink: #ec4899;
    --bg1: #1a0533;
    --bg2: #0d1b4b;
    --glass-bg: rgba(255,255,255,0.08);
    --glass-border: rgba(255,255,255,0.15);
    --glass-shadow: 0 8px 32px rgba(0,0,0,0.4);
    --text: rgba(255,255,255,0.92);
    --text-muted: rgba(255,255,255,0.55);
    --gradient: linear-gradient(135deg, var(--purple), var(--cyan));
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
    background: linear-gradient(135deg, var(--bg1) 0%, var(--bg2) 50%, #0a2a4a 100%);
    background-attachment: fixed;
    color: var(--text);
    font-family: 'Poppins', sans-serif;
    font-size: 1rem;
    line-height: 1.7;
    min-height: 100vh;
    overflow-x: hidden;
}

/* Aurora orbs */
.aurora-orb-1 {
    position: fixed;
    width: 700px; height: 700px;
    background: radial-gradient(circle, rgba(168,85,247,0.12) 0%, transparent 70%);
    top: -200px; left: -200px;
    animation: floatOrb 12s ease-in-out infinite alternate;
    pointer-events: none; z-index: 0;
    border-radius: 50%;
}
.aurora-orb-2 {
    position: fixed;
    width: 600px; height: 600px;
    background: radial-gradient(circle, rgba(6,182,212,0.1) 0%, transparent 70%);
    bottom: -150px; right: -150px;
    animation: floatOrb 15s ease-in-out infinite alternate-reverse;
    pointer-events: none; z-index: 0;
    border-radius: 50%;
}
.aurora-orb-3 {
    position: fixed;
    width: 400px; height: 400px;
    background: radial-gradient(circle, rgba(236,72,153,0.08) 0%, transparent 70%);
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    animation: floatOrb 18s ease-in-out infinite;
    pointer-events: none; z-index: 0;
    border-radius: 50%;
}

@keyframes floatOrb {
    0% { transform: translate(0,0) scale(1); }
    100% { transform: translate(80px,60px) scale(1.2); }
}

/* Glass card */
.glass-card {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
    border-radius: 16px;
    transition: all 0.3s ease;
}
.glass-card:hover {
    background: rgba(255,255,255,0.12);
    border-color: rgba(255,255,255,0.25);
    transform: translateY(-4px);
    box-shadow: 0 16px 48px rgba(0,0,0,0.5);
}

h1, h2, h3, h4, h5, h6 {
    font-family: 'Poppins', sans-serif;
    font-weight: 700;
}

/* Gradient text */
.gradient-text {
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

a { color: var(--cyan); text-decoration: none; transition: all 0.3s; }
a:hover { color: var(--purple); }

p { color: var(--text); }

blockquote {
    border-left: 3px solid var(--purple);
    background: rgba(168,85,247,0.08);
    padding: 1.5rem;
    margin: 2rem 0;
    border-radius: 0 12px 12px 0;
    color: var(--text);
}

code { background: rgba(168,85,247,0.15); color: var(--purple); padding: 0.2rem 0.5rem; border-radius: 4px; }
pre { background: rgba(255,255,255,0.05); border: 1px solid var(--glass-border); padding: 1.5rem; border-radius: 12px; overflow-x: auto; }

img { max-width: 100%; height: auto; }
.video-container { position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; border-radius: 12px; }
.video-container iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; }

/* ==========================================
   HEADER / NAV
   ========================================== */

#header {
    position: relative;
    z-index: 10;
}

#top-nav-bar {
    position: fixed;
    top: 0; left: 0; right: 0;
    z-index: 1000;
    background: transparent;
    transition: all 0.4s ease;
    padding: 1rem 0;
}

#top-nav-bar.scrolled {
    background: rgba(26,5,51,0.85);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border);
    padding: 0.5rem 0;
    box-shadow: 0 4px 30px rgba(0,0,0,0.3);
}

.navbar-brand {
    font-weight: 700;
    font-size: 1.4rem;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.navbar-toggler { border-color: var(--glass-border); }
.navbar-toggler-icon { filter: invert(1); }

.navbar-nav .nav-link {
    color: var(--text-muted) !important;
    font-weight: 500;
    font-size: 0.9rem;
    padding: 0.5rem 1rem !important;
    transition: all 0.3s;
    position: relative;
}
.navbar-nav .nav-link:hover { color: var(--text) !important; }
.navbar-nav .nav-link::after {
    content: '';
    position: absolute; bottom: 0; left: 1rem; right: 1rem;
    height: 1px; background: var(--gradient);
    transform: scaleX(0); transition: transform 0.3s;
}
.navbar-nav .nav-link:hover::after { transform: scaleX(1); }

/* Hero */
#cover-hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 5rem 0;
    position: relative;
    z-index: 1;
}

#cover-hero h1 {
    font-size: clamp(2.5rem, 6vw, 5rem);
    font-weight: 700;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    line-height: 1.1;
    margin-bottom: 1.5rem;
}

#cover-hero p { color: var(--text-muted); font-size: 1.15rem; font-weight: 300; max-width: 560px; margin: 0 auto; }

.btn-glass {
    padding: 0.75rem 2rem;
    background: var(--gradient);
    color: white;
    border: none;
    border-radius: 50px;
    font-weight: 600;
    font-size: 0.9rem;
    transition: all 0.3s;
    display: inline-block;
    margin-top: 2rem;
    box-shadow: 0 4px 20px rgba(168,85,247,0.4);
}
.btn-glass:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(168,85,247,0.6); color: white; }

/* Social icons */
#btemplates-social .nav-link { color: var(--text-muted); font-size: 1.1rem; padding: 0.3rem 0.5rem; transition: all 0.3s; }
#btemplates-social .nav-link:hover { color: var(--purple); }

/* ==========================================
   HOME SECTIONS
   ========================================== */

#btemplates-1 { padding: 4rem 0; position: relative; z-index: 1; }

/* Swiper slider */
.swiper { width: 100%; padding-bottom: 3rem !important; }
.swiper-slide { border-radius: 16px; overflow: hidden; }
.swiper-pagination-bullet { background: var(--text-muted); }
.swiper-pagination-bullet-active { background: var(--purple); }
.swiper-button-next, .swiper-button-prev { color: var(--purple); }

/* Post cards */
.btemplates-post {
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    overflow: hidden;
    transition: all 0.3s ease;
    margin-bottom: 1.5rem;
}
.btemplates-post:hover {
    transform: translateY(-6px);
    border-color: rgba(168,85,247,0.4);
    box-shadow: 0 20px 60px rgba(0,0,0,0.5), 0 0 0 1px rgba(168,85,247,0.2);
}
.btemplates-post img { width: 100%; height: 200px; object-fit: cover; }
.bt-post-title { padding: 1.25rem; }
.bt-post-title a { font-weight: 600; font-size: 1rem; background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.bt-post-date { color: var(--text-muted); font-size: 0.78rem; padding: 0 1.25rem; }
.bt-post-content { color: var(--text-muted); font-size: 0.88rem; padding: 0.5rem 1.25rem 1.25rem; }

/* Tags section */
#btemplates-2 {
    padding: 3rem 0;
    position: relative;
    z-index: 1;
}

.btemplates-tags { list-style: none; padding: 0; display: flex; flex-wrap: wrap; gap: 1rem; justify-content: center; }
.btemplates-tags li a, .bt-tag {
    display: inline-block;
    padding: 0.5rem 1.5rem;
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 50px;
    color: var(--text);
    font-size: 0.9rem;
    font-weight: 500;
    backdrop-filter: blur(10px);
    transition: all 0.3s;
    text-decoration: none;
}
.btemplates-tags li a:hover, .bt-tag:hover {
    background: rgba(168,85,247,0.2);
    border-color: var(--purple);
    color: var(--text);
    transform: translateY(-2px);
}

#btemplates-3 { padding: 3rem 0; position: relative; z-index: 1; }

/* Section title */
.glass-section-title {
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 2rem;
}

/* ==========================================
   MAIN POSTS
   ========================================== */

#main { padding: 3rem 0; position: relative; z-index: 1; }

.post { border-bottom: 1px solid var(--glass-border); padding: 3rem 0; }

.post-title { margin-bottom: 1.5rem; }
.post-title a {
    font-size: clamp(1.5rem, 3vw, 2.5rem);
    font-weight: 700;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    line-height: 1.2;
}

.post-thumbnail { margin-bottom: 2rem; border-radius: 16px; overflow: hidden; }
.post-thumbnail img { width: 100%; transition: transform 0.4s ease; }
.post-thumbnail:hover img { transform: scale(1.03); }

.post-content p { color: var(--text); line-height: 1.8; }
.post-body { color: var(--text); line-height: 1.8; }
.post-body h2, .post-body h3 { background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; margin-top: 2rem; }
.post-body img { border-radius: 12px; margin: 1.5rem 0; }
.post-body a { color: var(--purple); text-decoration: underline; text-underline-offset: 3px; }

.post-labels a {
    display: inline-block; padding: 0.2rem 0.75rem;
    background: rgba(168,85,247,0.15); color: var(--purple);
    border-radius: 50px; font-size: 0.78rem; font-weight: 600;
    margin-right: 0.3rem; transition: all 0.3s;
}
.post-labels a:hover { background: rgba(168,85,247,0.3); }

.post-footer { padding: 1rem 0 0; border-top: 1px solid var(--glass-border); margin-top: 1.5rem; }
.post-share a { color: var(--text-muted); margin-right: 0.75rem; font-size: 1.1rem; transition: all 0.3s; }
.post-share a:hover { color: var(--purple); }

.post-byline { font-size: 0.82rem; color: var(--text-muted); margin-bottom: 1.5rem; }

/* Pagination */
.blog-pager { padding: 2rem 0; display: flex; gap: 1rem; flex-wrap: wrap; }
.blog-pager a { padding: 0.6rem 1.5rem; border-radius: 50px; background: var(--glass-bg); border: 1px solid var(--glass-border); color: var(--text); font-size: 0.9rem; font-weight: 500; backdrop-filter: blur(10px); transition: all 0.3s; }
.blog-pager a:hover { background: rgba(168,85,247,0.2); border-color: var(--purple); color: var(--text); }

/* Comments */
#comments { margin-top: 3rem; padding-top: 2rem; border-top: 1px solid var(--glass-border); }
#comments h3 { background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; font-size: 1.3rem; margin-bottom: 1.5rem; }
.comment-block { background: var(--glass-bg); border: 1px solid var(--glass-border); border-radius: 12px; padding: 1.5rem; margin-bottom: 1rem; backdrop-filter: blur(10px); }
.comment-author { background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; font-weight: 600; }
.comment-header { color: var(--text-muted); font-size: 0.8rem; }
.comment-content { color: var(--text); margin-top: 0.5rem; }

/* Author profile */
.author-profile { background: var(--glass-bg); border: 1px solid var(--glass-border); border-radius: 16px; padding: 2rem; backdrop-filter: blur(20px); margin-top: 2rem; }
.author-image { width: 80px; height: 80px; border-radius: 50%; object-fit: cover; border: 2px solid var(--purple); margin-right: 1.5rem; }
.author-name a { background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; font-weight: 600; }
.author-desc { color: var(--text-muted); font-size: 0.9rem; margin-top: 0.25rem; }

/* Widget styles */
.widget-title h2, .widget > h2, h2.title {
    font-size: 1rem; font-weight: 600;
    background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
    border-bottom: 1px solid var(--glass-border); padding-bottom: 0.75rem; margin-bottom: 1.5rem;
}

.PopularPosts a { display: flex; gap: 1rem; align-items: center; padding: 0.75rem; background: var(--glass-bg); border: 1px solid var(--glass-border); border-radius: 12px; margin-bottom: 0.75rem; backdrop-filter: blur(10px); transition: all 0.3s; }
.PopularPosts a:hover { background: rgba(255,255,255,0.12); }
.popular-thumbnail img { width: 60px; height: 60px; object-fit: cover; border-radius: 8px; }
.popular-post-title { color: var(--text); font-weight: 600; font-size: 0.88rem; }
.popular-post-description { color: var(--text-muted); font-size: 0.78rem; margin-top: 0.2rem; }

.search-form .form-control { background: var(--glass-bg); border: 1px solid var(--glass-border); color: var(--text); border-radius: 50px; padding-left: 1rem; backdrop-filter: blur(10px); }
.search-form .form-control::placeholder { color: var(--text-muted); }
.search-form .form-control:focus { border-color: var(--purple); box-shadow: 0 0 0 3px rgba(168,85,247,0.15); background: var(--glass-bg); color: var(--text); }
.search-form .btn-primary { background: var(--gradient); border: none; border-radius: 50px; color: white; }

.contact-form-widget .form-control { background: var(--glass-bg); border: 1px solid var(--glass-border); color: var(--text); border-radius: 12px; }
.contact-form-widget .form-control:focus { border-color: var(--purple); box-shadow: 0 0 0 3px rgba(168,85,247,0.15); }
.contact-form-button { background: linear-gradient(135deg,var(--purple),var(--cyan)) !important; border: none !important; color: white !important; border-radius: 50px !important; cursor: pointer; font-weight: 600; }

.Label li { display: inline-block; margin: 0.2rem; }
.Label li a { background: var(--glass-bg); border: 1px solid var(--glass-border); color: var(--text); border-radius: 50px; padding: 0.2rem 0.75rem; font-size: 0.8rem; transition: all 0.3s; }
.Label li a:hover { border-color: var(--purple); color: var(--purple); }

/* ==========================================
   FOOTER
   ========================================== */

#footer {
    background: rgba(26,5,51,0.6);
    backdrop-filter: blur(20px);
    border-top: 1px solid var(--glass-border);
    padding: 4rem 0 2rem;
    position: relative;
    z-index: 1;
}
#footer .widget > h2, #footer .widget-title h2 { background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
#footer a { color: var(--text-muted); transition: color 0.3s; }
#footer a:hover { color: var(--purple); }
#footer ul { list-style: none; padding: 0; }
#footer ul li { border-bottom: 1px solid var(--glass-border); padding: 0.4rem 0; }

.social a { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 50%; background: var(--glass-bg); border: 1px solid var(--glass-border); color: var(--text-muted); margin-right: 0.4rem; font-size: 1.1rem; transition: all 0.3s; }
.social a:hover { background: rgba(168,85,247,0.2); border-color: var(--purple); color: var(--purple); }

#bottom { background: rgba(26,5,51,0.8); border-top: 1px solid var(--glass-border); padding: 1.25rem 0; color: var(--text-muted); font-size: 0.85rem; position: relative; z-index: 1; }
#bottom a { color: var(--cyan); }

/* Back to top */
#back-top { position: fixed; bottom: 2rem; right: 2rem; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--gradient); color: white; z-index: 9000; font-size: 1.1rem; opacity: 0; transition: all 0.3s; box-shadow: 0 4px 20px rgba(168,85,247,0.5); text-decoration: none; }
#back-top.visible { opacity: 1; }
#back-top:hover { transform: translateY(-3px); box-shadow: 0 8px 30px rgba(168,85,247,0.7); color: white; }

/* Search modal */
.modal-content { background: rgba(26,5,51,0.9); backdrop-filter: blur(30px); border: 1px solid var(--glass-border); border-radius: 20px; }
.modal-header { border-bottom: 1px solid var(--glass-border); }
.modal-title { background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; font-weight: 700; }
.btn-close { filter: invert(1); }
.modal-body .form-control { background: var(--glass-bg); border: 1px solid var(--glass-border); color: var(--text); border-radius: 50px; }
.modal-body .form-control:focus { border-color: var(--purple); box-shadow: none; }
.modal-body .btn { background: var(--gradient); border: none; color: white; border-radius: 50px; }

/* Error 404 */
#btemplates-error-404 { text-align: center; padding: 5rem 0; }
#btemplates-error-404 h3 { font-size: clamp(2rem, 5vw, 4rem); background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; font-weight: 700; }

/* Post navigation */
#btemplates-next-prev { display: flex; gap: 1rem; margin: 2rem 0; flex-wrap: wrap; }
#next-post a, #previous-post a { display: block; padding: 1.25rem; background: var(--glass-bg); border: 1px solid var(--glass-border); border-radius: 16px; color: var(--text); font-weight: 500; backdrop-filter: blur(10px); transition: all 0.3s; }
#next-post a:hover, #previous-post a:hover { border-color: var(--purple); background: rgba(168,85,247,0.1); color: var(--text); }

.blog-feeds, .post-feeds { font-size: 0.8rem; color: var(--text-muted); padding: 0.5rem 0; }
.feed-link { color: var(--cyan); margin-left: 0.5rem; }

/* Scroll reveal */
.reveal { opacity: 0; transform: translateY(40px); transition: opacity 0.7s ease, transform 0.7s ease; }
.reveal.visible { opacity: 1; transform: translateY(0); }

@media (max-width: 768px) {
    #cover-hero { min-height: 70vh; padding: 5rem 0 3rem; }
    #cover-hero h1 { font-size: 2.5rem; }
    #btemplates-social { display: none !important; }
}

b:if.b:template-skin:
body#layout { max-width: 100% !important; padding: 0 1.5rem; }
body#layout #header, body#layout #footer, body#layout #bottom { clear: both; }
body#layout #page_body { float: left; width: 65%; }
body#layout #footer .section { width: 32%; float: left; }

body.script:
var blogurl = ''.replace('?m=1','');
var blogtitle = '';
//
$j = jQuery.noConflict();
$j(document).ready(function() {

    $j('#this-year').text(new Date().getFullYear());

    // Scroll nav effect
    $j(window).scroll(function() {
        if ($j(this).scrollTop() > 50) {
            $j('#top-nav-bar').addClass('scrolled');
            if ($j(this).scrollTop() > 300) { $j('#back-top').addClass('visible'); } else { $j('#back-top').removeClass('visible'); }
        } else {
            $j('#top-nav-bar').removeClass('scrolled');
            $j('#back-top').removeClass('visible');
        }
    });

    $j('#back-top').click(function() { $j('html,body').animate({ scrollTop: 0 }, 600); });

    // GSAP ScrollTrigger reveal
    if (typeof gsap !== 'undefined' && typeof ScrollTrigger !== 'undefined') {
        gsap.registerPlugin(ScrollTrigger);
        gsap.utils.toArray('.reveal').forEach(function(el) {
            gsap.fromTo(el, { opacity: 0, y: 50 }, { opacity: 1, y: 0, duration: 0.8, ease: 'power2.out', scrollTrigger: { trigger: el, start: 'top 85%', once: true } });
        });
        gsap.utils.toArray('.btemplates-post').forEach(function(el) {
            gsap.fromTo(el, { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.6, ease: 'power2.out', scrollTrigger: { trigger: el, start: 'top 90%', once: true } });
        });
    }

    // Avatar upgrade
    $j('.avatar-image-container img').each(function() { var s=$j(this).attr('src'); if(s) $j(this).attr('src',s.replace('/s35/','/s100/')); });

    var socialNetworks = ['facebook','twitter','instagram','pinterest','youtube','linkedin','github','tiktok','mastodon','whatsapp','snapchat','tumblr','vimeo','soundcloud','spotify','reddit','dribbble','behance'];
    $j('#btemplates-social li a').each(function() {
        var la=$j(this).attr('href').toLowerCase(); var el=$j(this);
        el.addClass('nav-link'); el.parent('li').addClass('nav-item');
        $j.each(socialNetworks,function(i,sn){ if(la.indexOf(sn)!==-1){el.html('<i class="fab fa-'+sn+'"></i>');return false;} });
    });
    $j('#btemplates-social .nav').removeClass('d-none');

    $j('#footer .LinkList li a').each(function() {
        var la=$j(this).attr('href').toLowerCase(); var el=$j(this); var widget=el.closest('.widget');
        $j.each(socialNetworks,function(i,sn){ if(la.indexOf(sn)!==-1){widget.addClass('social');el.html('<i class="fab fa-'+sn+'"></i>');el.parent().replaceWith(el);return false;} });
    });

    $j('.LinkList a,.Text a').each(function(){ var h=$j(this).attr('href'); if(h&&h.indexOf('#bt-home')!==-1){$j(this).attr('href',blogurl);} });

    // Swiper init (if present)
    function initSwiper() {
        if (document.querySelector('#featured-swiper .swiper-slide')) {
            new Swiper('#featured-swiper', { loop: true, autoplay: { delay: 4000, disableOnInteraction: false }, pagination: { el: '.swiper-pagination', clickable: true }, navigation: { nextEl: '.swiper-button-next', prevEl: '.swiper-button-prev' }, slidesPerView: 1, spaceBetween: 20, breakpoints: { 768: { slidesPerView: 2 }, 1024: { slidesPerView: 3 } } });
        }
    }

    // Post fetching
    function btemplatesJqueryGetPosts(container, count, type, thumbSize, style, exclude) {
        var feedUrl = blogurl + '/feeds/posts/default';
        if (type && type.indexOf('tag:') !== -1) { feedUrl += '/-/' + encodeURIComponent(type.replace('tag:', '')); }
        feedUrl += '?alt=json&max-results=' + count;
        $j.getJSON(feedUrl + '&callback=?', function(data) {
            var posts = data.feed.entry || [];
            var html = '';
            $j.each(posts, function(i, entry) {
                var title = entry.title.$t;
                var url = ''; $j.each(entry.link, function(j, link) { if (link.rel === 'alternate') { url = link.href; return false; } });
                var thumb = thumbSize > 0 && entry['media$thumbnail'] ? entry['media$thumbnail'].url.replace(/\/s[0-9]+(-c)?\//, '/s' + thumbSize + '-c/') : '';
                var date = entry.published ? entry.published.$t.substring(0,10) : '';
                var summary = entry.summary ? entry.summary.$t.substring(0,120) : '';
                if (style === 'slider') {
                    html += '<div class="swiper-slide"><div class="btemplates-post glass-card">' + (thumb ? '<img src="' + thumb + '" alt="' + title + '" style="width:100%;height:200px;object-fit:cover;"/>' : '') + '<div class="bt-post-title"><a href="' + url + '">' + title + '</a></div><div class="bt-post-date">' + date + '</div></div></div>';
                } else if (style === 'bloglist') {
                    html += '<div class="col-12 col-sm-6 col-md-4 mb-3"><div class="btemplates-post glass-card">' + (thumb ? '<img src="' + thumb + '" alt="' + title + '"/>' : '') + '<div class="bt-post-title"><a href="' + url + '">' + title + '</a></div><div class="bt-post-date">' + date + '</div></div></div>';
                } else {
                    html += '<div class="btemplates-post glass-card mb-3"><div class="bt-post-title"><a href="' + url + '">' + title + '</a></div><div class="bt-post-date">' + date + '</div><div class="bt-post-content">' + summary + '</div></div>';
                }
            });
            if (style === 'slider') {
                $j('#swiper-posts-wrapper').html(html);
                initSwiper();
            } else if (style === 'bloglist') {
                container.html('<div class="row">' + html + '</div>');
            } else {
                container.html(html);
            }
        }).fail(function() { container.html('<p style="color:var(--text-muted);">Could not load posts.</p>'); });
    }

    // Load swiper posts
    btemplatesJqueryGetPosts($j('#swiper-posts-wrapper'), 6, 'latest', 800, 'slider', false);

    var re = /^(\d+)-(latest|tag:.*?)-(\d+)px-([\w]+)(?:-(.*?))?$/i;
    $j('.widget-content').each(function() {
        var text = $j(this).text().trim();
        if (re.exec(text)) { var m=text.match(re); var self=$j(this); self.html(''); btemplatesJqueryGetPosts(self,m[1],m[2],m[3],m[4]||'list',m[5]||false); }
    });
});
